#!/usr/bin/env bash
# ==============================================================================
# Sky-Lux CRM — Production Fast Rollback & Disaster Recovery Wizard
# Generated by the /wizard skill.
#
# Walks a human operator step by step through a fast, safe rollback of
# Docker containers and/or PostgreSQL database snapshots on VPS.
# ==============================================================================

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

TOTAL_STAGES=4
_STAGE_INDEX=0
PROJECT_DIR="${PROJECT_DIR:-/opt/skylux}"
ENV_FILE="$PROJECT_DIR/.env"
COMPOSE_FILE="$PROJECT_DIR/docker-compose.prod.yml"

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

banner() {
  _clear
  printf '\n%s%s  🚀 %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages · Interactive Rollback & Recovery Guide%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '  This wizard guides you through safely reverting container versions\n'
  printf '  and restoring database snapshots to recover from a bad deployment.\n'
  printf '  Stop any time with Ctrl-C.\n\n'
  pause "Press Enter to start incident recovery..."
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }
ok()   { printf '  %s✔ %s%s\n' "$GREEN" "$1" "$RESET"; }

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

finish() {
  _clear
  printf '\n%s%s  ✔ Rollback & Recovery Procedure Complete%s\n\n' "$BOLD" "$GREEN" "$RESET"
  note "System status verified. Containers are up and responding to healthchecks."
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

banner "Sky-Lux CRM Production Rollback Wizard"

# ── STAGE 1: SYSTEM HEALTH & INCIDENT DIAGNOSIS ────────────────────────────
stage "Khảo sát Hiện trạng & Chẩn đoán Sự cố"
say "Đang kiểm tra trạng thái hoạt động của các dịch vụ Sky-Lux..."

cd "$PROJECT_DIR" 2>/dev/null || true

CURRENT_VERSION="unknown"
if [[ -f "$ENV_FILE" ]]; then
  CURRENT_VERSION=$(grep '^APP_VERSION=' "$ENV_FILE" 2>/dev/null | cut -d '=' -f2 || echo "unknown")
fi
step "Phiên bản ứng dụng đang chạy (APP_VERSION): $BOLD$CURRENT_VERSION$RESET"

if command -v docker >/dev/null 2>&1 && [[ -f "$COMPOSE_FILE" ]]; then
  say "Trạng thái container Docker hiện tại:"
  printf '\n'
  docker compose -f "$COMPOSE_FILE" ps || true
  printf '\n'

  UNHEALTHY_COUNT=$(docker compose -f "$COMPOSE_FILE" ps --filter "status=exited" -q | wc -l)
  if [[ "$UNHEALTHY_COUNT" -gt 0 ]]; then
    warn "Phát hiện $UNHEALTHY_COUNT container đang ở trạng thái ngưng hoạt động (Exited)."
    note "Trích xuất 10 dòng log mới nhất từ backend:"
    docker compose -f "$COMPOSE_FILE" logs --tail=10 backend 2>/dev/null || true
  else
    ok "Tất cả các container cơ bản đang chạy."
  fi
else
  warn "Không thể truy cập Docker Compose tại $PROJECT_DIR."
fi

pause

# ── STAGE 2: TARGET VERSION SELECTION ──────────────────────────────────────
stage "Xác định Phiên bản Ứng dụng Cần Khôi phục"
say "Lựa chọn Git commit SHA hoặc tag của phiên bản trước sự cố."

PREV_VERSION=""
if [[ -f "$PROJECT_DIR/.env.previous" ]]; then
  PREV_VERSION=$(grep '^APP_VERSION=' "$PROJECT_DIR/.env.previous" 2>/dev/null | cut -d '=' -f2 || true)
fi

TARGET_APP_VERSION="$PREV_VERSION"
if [[ -n "$PREV_VERSION" ]]; then
  ok "Phát hiện phiên bản ổn định gần nhất trong .env.previous: $BOLD$PREV_VERSION$RESET"
  if confirm "Bạn có muốn rollback về phiên bản này ($PREV_VERSION)?"; then
    TARGET_APP_VERSION="$PREV_VERSION"
  else
    TARGET_APP_VERSION=""
  fi
fi

if [[ -z "$TARGET_APP_VERSION" ]]; then
  step "Nhập mã Git Commit SHA bạn muốn khôi phục:"
  printf '  %sMã Version SHA:%s ' "$BOLD" "$RESET"
  read -r TARGET_APP_VERSION
fi

step "Phiên bản mục tiêu được chọn: $BOLD$TARGET_APP_VERSION$RESET"
pause

# ── STAGE 3: DATABASE RESTORE DECISION ────────────────────────────────────
stage "Khôi phục Cơ sở Dữ liệu (Tùy chọn)"
say "Nếu sự cố do lỗi cấu trúc CSDL (migration lỗi), bạn có thể khôi phục từ snapshot."

RESTORE_DB="no"
CHOSEN_BACKUP=""
BACKUP_DIR="$PROJECT_DIR/backups"

if [[ -d "$BACKUP_DIR" ]]; then
  say "Danh sách 5 bản sao lưu gần nhất tại $BACKUP_DIR:"
  # shellcheck disable=SC2012
  ls -lt "$BACKUP_DIR"/skylux_*.sql.gz 2>/dev/null | head -n 5 | awk '{print "    " $9 " (" $5 " bytes - " $6 " " $7 " " $8 ")"}' || true
  printf '\n'

  if confirm "Bạn có cần khôi phục lại dữ liệu CSDL từ bản snapshot không?"; then
    RESTORE_DB="yes"
    LATEST_SNAPSHOT=$(ls -t "$BACKUP_DIR"/skylux_*.sql.gz 2>/dev/null | head -n 1 || true)
    if [[ -n "$LATEST_SNAPSHOT" ]]; then
      step "Bản snapshot mới nhất: $LATEST_SNAPSHOT"
      if confirm "Sử dụng bản snapshot mới nhất này?"; then
        CHOSEN_BACKUP="$LATEST_SNAPSHOT"
      fi
    fi

    if [[ -z "$CHOSEN_BACKUP" ]]; then
      printf '  %sNhập đường dẫn file backup .sql.gz:%s ' "$BOLD" "$RESET"
      read -r CHOSEN_BACKUP
    fi

    warn "CHÚ Ý: Khôi phục CSDL sẽ ghi đè toàn bộ dữ liệu hiện có bằng bản sao lưu."
    if ! confirm "Bạn có chắc chắn 100% muốn phục hồi CSDL từ file này?"; then
      say "Đã hủy thao tác phục hồi CSDL. Chỉ thực hiện rollback phiên bản mã nguồn."
      RESTORE_DB="no"
      CHOSEN_BACKUP=""
    fi
  else
    say "Bỏ qua bước phục hồi CSDL. Dữ liệu hiện tại được giữ nguyên."
  fi
else
  note "Thư mục sao lưu $BACKUP_DIR chưa tồn tại hoặc rỗng."
fi

pause

# ── STAGE 4: EXECUTION & VERIFICATION ──────────────────────────────────────
stage "Thực thi Rollback & Kiểm tra Sức khỏe"
say "Bắt đầu áp dụng quy trình phục hồi về $TARGET_APP_VERSION..."

if [[ "$RESTORE_DB" == "yes" && -n "$CHOSEN_BACKUP" ]]; then
  step "Đang phục hồi cơ sở dữ liệu từ $CHOSEN_BACKUP..."
  bash "$PROJECT_DIR/infra/scripts/restore-db.sh" "$CHOSEN_BACKUP"
  ok "Phục hồi cơ sở dữ liệu hoàn tất."
fi

step "Thực thi rollback container qua rollback.sh..."
bash "$PROJECT_DIR/infra/scripts/rollback.sh" "$TARGET_APP_VERSION"
ok "Container đã được xoay vòng về phiên bản $TARGET_APP_VERSION."

step "Kiểm tra kiểm toán sức khỏe tổng thể:"
if docker compose -f "$COMPOSE_FILE" exec -T nginx wget -qO- http://backend:3001/api/health >/dev/null 2>&1; then
  ok "API Healthcheck 200 OK — Hệ thống đang vận hành ổn định."
else
  warn "Healthcheck chưa phản hồi ngay lập tức. Hãy kiểm tra logs hệ thống:"
  say "docker compose -f $COMPOSE_FILE logs -f"
fi

pause "Bấm Enter để xem tổng kết hoàn tất."

finish
